package com.zerotrust.internalresource.audit;
import jakarta.servlet.http.HttpServletRequest;import org.springframework.stereotype.Component;
@Component public class ResourceIdResolver{public String resolve(HttpServletRequest request){String path=request.getRequestURI();String method=request.getMethod();if(path.equals("/api/files")||path.startsWith("/api/files/"))return "internal-files";if(path.equals("/api/devices")||path.startsWith("/api/devices/"))return "internal-devices";if(method.equals("GET")&&path.equals("/api/test-resources/read"))return "test-resource-read";if(method.equals("POST")&&path.equals("/api/test-resources/create"))return "test-resource-create";if(method.equals("PUT")&&path.startsWith("/api/test-resources/update/"))return "test-resource-update";if(method.equals("DELETE")&&path.startsWith("/api/test-resources/delete/"))return "test-resource-delete";return null;}}
